@@ -105,14 +105,14 @@ add_plan_ledger_row() {
   local id="$1" status="$2" tmp
   tmp="$(mktemp "${BATS_TEST_TMPDIR}/planledger.XXXXXX")"
   jq --arg id "$id" --arg status "$status" \
-    '.plans += [{"id": $id, "status": $status, "completed_at": "2026-07-05T00:00:00Z"}]' \
+    '.plans += [{"id": $id, "status": $status, "merged_at": "2026-07-05T00:00:00Z"}]' \
     "$PLANS_LEDGER" > "$tmp" && mv "$tmp" "$PLANS_LEDGER"
 }

 # --- 1. UAT-009 default dry-run no-op ----------------------------------------

 @test "UAT-009 default dry-run: deletes nothing, prints a manifest, cost.jsonl byte-identical" {
-  add_plan_ledger_row PLAN-005 completed
+  add_plan_ledger_row PLAN-005 merged
   {
     printf '# Cost: PLAN-005\n\n'
     section Planning 10 20 30 40 sess-a
@@ -143,7 +143,7 @@ add_plan_ledger_row() {
 # --- 2. UAT-008 represented -> deleted under --confirm -----------------------

 @test "UAT-008 represented PLAN folder: manifest DELETE, removed under --confirm, cost.jsonl untouched" {
-  add_plan_ledger_row PLAN-006 completed
+  add_plan_ledger_row PLAN-006 merged
   {
     printf '# Cost: PLAN-006\n\n'
     section Planning 10 20 30 40 sess-b
@@ -182,7 +182,7 @@ add_plan_ledger_row() {
 # --- 3. UAT-008 unrepresented / unparseable -> BLOCKED ----------------------

 @test "UAT-008 value-mismatched phase: BLOCKED, survives --confirm" {
-  add_plan_ledger_row PLAN-007 completed
+  add_plan_ledger_row PLAN-007 merged
   {
     printf '# Cost: PLAN-007\n\n'
     section Execution 999 1 1 1 sess-c
@@ -196,7 +196,7 @@ add_plan_ledger_row() {
 }

 @test "UAT-008 unparseable phase (non-numeric bucket): BLOCKED reason unparseable, survives --confirm" {
-  add_plan_ledger_row PLAN-011 completed
+  add_plan_ledger_row PLAN-011 merged
   {
     printf '# Cost: PLAN-011\n\n'
     printf '## Execution\n\n'
@@ -219,7 +219,7 @@ add_plan_ledger_row() {
 # --- 4. UAT-008 dry-run manifest columns -------------------------------------

 @test "UAT-008 dry-run manifest: {folder, phases verified, phases blocking} per folder" {
-  add_plan_ledger_row PLAN-008 completed
+  add_plan_ledger_row PLAN-008 merged
   {
     printf '# Cost: PLAN-008\n\n'
     section Planning 10 20 30 40 sess-d
@@ -287,7 +287,7 @@ add_plan_ledger_row() {
 # --- 7. Needs-backfill -> BLOCKED (verify-only, DP-002/COV-001) --------------

 @test "needs-backfill: a phase with no ledger row is BLOCKED (needs-backfill); cost.jsonl byte-identical in BOTH modes" {
-  add_plan_ledger_row PLAN-009 completed
+  add_plan_ledger_row PLAN-009 merged
   {
     printf '# Cost: PLAN-009\n\n'
     section Planning 10 20 30 40 sess-g

@@ -35,7 +35,7 @@ setup() {
       "allocated_at": "2026-01-01T00:00:00Z",
       "source": "allocated",
       "subject": "x",
-      "status": "allocated"
+      "status": "ready"
     }
   ]
 }
@@ -61,11 +61,11 @@ _row_field() {
     "$SANDBOX/$LEDGER_REL"
 }

-@test "1: completed patch exits 0, sets status+completed_at, preserves other fields" {
-  run _update PLAN-001 '{"status":"completed","completed_at":"2026-07-05T00:00:00Z"}'
+@test "1: merged patch exits 0, sets status+merged_at, preserves other fields" {
+  run _update PLAN-001 '{"status":"merged","merged_at":"2026-07-05T00:00:00Z"}'
   [ "$status" -eq 0 ]
-  [ "$(_row_field status)" = "completed" ]
-  [ "$(_row_field completed_at)" = "2026-07-05T00:00:00Z" ]
+  [ "$(_row_field status)" = "merged" ]
+  [ "$(_row_field merged_at)" = "2026-07-05T00:00:00Z" ]
   [ "$(_row_field id)" = "PLAN-001" ]
   [ "$(_row_field allocated_at)" = "2026-01-01T00:00:00Z" ]
   [ "$(_row_field source)" = "allocated" ]
@@ -76,19 +76,19 @@ _row_field() {
   run _update PLAN-001 '{"status":"bogus"}'
   [ "$status" -eq 6 ]
   grep -qF "non-canonical status 'bogus'" <<<"$output"
-  [ "$(_row_field status)" = "allocated" ]
+  [ "$(_row_field status)" = "ready" ]
 }

 @test "3: status-less patch updates only the targeted field, status untouched" {
   run _update PLAN-001 '{"subject":"new subject"}'
   [ "$status" -eq 0 ]
   [ "$(_row_field subject)" = "new subject" ]
-  [ "$(_row_field status)" = "allocated" ]
+  [ "$(_row_field status)" = "ready" ]
 }

 @test "4: patch for a non-existent row exits 4 and mutates nothing" {
   before="$(cat "$SANDBOX/$LEDGER_REL")"
-  run _update PLAN-999 '{"status":"completed"}'
+  run _update PLAN-999 '{"status":"merged"}'
   [ "$status" -eq 4 ]
   [ "$(cat "$SANDBOX/$LEDGER_REL")" = "$before" ]
 }
@@ -98,14 +98,22 @@ _row_field() {
   [ "$status" -eq 5 ]
 }

-@test "6: allocated, completed, and abandoned are all accepted" {
-  for s in allocated completed abandoned; do
+@test "6: ready, merged, and abandoned are all accepted" {
+  for s in ready merged abandoned; do
     run _update PLAN-001 "{\"status\":\"$s\"}"
     [ "$status" -eq 0 ]
     [ "$(_row_field status)" = "$s" ]
   done
 }

+@test "6b: allocated, completed, and specified are all rejected with exit 6" {
+  for s in allocated completed specified; do
+    run _update PLAN-001 "{\"status\":\"$s\"}"
+    [ "$status" -eq 6 ]
+    grep -qF "non-canonical status '$s'" <<<"$output"
+  done
+}
+
 @test "7: wrong arg count exits 2" {
   run bash "$SANDBOX/.specify/extensions/gaia/lib/plan-ledger-update.sh" "$SANDBOX" PLAN-001
   [ "$status" -eq 2 ]

@@ -2,7 +2,9 @@
 # Tests for `.specify/extensions/gaia/lib/plan-reconcile.sh`, the plan-arm
 # counterpart to `spec-reconcile.sh` (see spec-reconcile.bats for the spec
 # arm). Orchestrator-driven: the caller already knows the merge is confirmed
-# and the plan_id, so there is no gh/PR scan here, unlike the spec arm.
+# and the plan_id, so there is no gh/PR scan here, unlike the spec arm. Plan
+# age anchors on `merged_at`, so this arm writes status "merged", not the
+# retired "completed".
 #
 # Does NOT use helpers/tmp-spec-repo.sh: that shared harness seeds only the
 # specs ledger and does not copy plan-ledger-update.sh. Mirrors the self-copy
@@ -37,7 +39,7 @@ setup() {
       "allocated_at": "2026-01-01T00:00:00Z",
       "source": "allocated",
       "subject": "x",
-      "status": "allocated"
+      "status": "ready"
     }
   ]
 }
@@ -63,12 +65,12 @@ _row_field() {
     "$SANDBOX/$LEDGER_REL"
 }

-@test "1: allocated PLAN-005 flips to completed with an ISO completed_at, exit 0" {
+@test "1: ready PLAN-005 flips to merged with an ISO merged_at, exit 0" {
   run _reconcile PLAN-005
   [ "$status" -eq 0 ]
-  grep -qF "reconciled PLAN-005 -> completed" <<<"$output"
-  [ "$(_row_field PLAN-005 status)" = "completed" ]
-  case "$(_row_field PLAN-005 completed_at)" in
+  grep -qF "reconciled PLAN-005 -> merged" <<<"$output"
+  [ "$(_row_field PLAN-005 status)" = "merged" ]
+  case "$(_row_field PLAN-005 merged_at)" in
     [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z) ;;
     *) return 1 ;;
   esac
@@ -79,15 +81,15 @@ _row_field() {
   [ ! -d "$SANDBOX/.gaia/local/plans/PLAN-005" ]
   run _reconcile PLAN-005
   [ "$status" -eq 0 ]
-  [ "$(_row_field PLAN-005 status)" = "completed" ]
+  [ "$(_row_field PLAN-005 status)" = "merged" ]
 }

-@test "2: idempotent; a second run re-stamps completed and exits 0" {
+@test "2: idempotent; a second run re-stamps merged and exits 0" {
   run _reconcile PLAN-005
   [ "$status" -eq 0 ]
   run _reconcile PLAN-005
   [ "$status" -eq 0 ]
-  [ "$(_row_field PLAN-005 status)" = "completed" ]
+  [ "$(_row_field PLAN-005 status)" = "merged" ]
 }

 @test "3: a non-PLAN-NNN id is a no-op, exits 0, leaves the ledger unchanged" {
@@ -115,9 +117,9 @@ _row_field() {
   [ "$before" = "$after" ]
 }

-@test "5: the plans status vocabulary guard holds; plan-reconcile never writes merged" {
+@test "5: the plans status vocabulary guard holds; plan-reconcile never writes the retired 'completed' status" {
   run _reconcile PLAN-005
   [ "$status" -eq 0 ]
-  grep -qF -- "-> merged" <<<"$output" && return 1
-  [ "$(_row_field PLAN-005 status)" = "completed" ]
+  grep -qF -- "-> completed" <<<"$output" && return 1
+  [ "$(_row_field PLAN-005 status)" = "merged" ]
 }

